discrete ImageAcquisitionSystem
port:
    event input real StartSignal;
    event output real ExposureComplete;
    event output real ReadComplete;
state:
    initial state State1
        when entry() then
            statehold(0);
        end;
        when receive(StartSignal) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(State3);
            out
                send(ExposureComplete, 1);
        end;
    end;

    state State3
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State4);
            out
                send(ReadComplete, 1);
        end;
    end;

    state State4
        when entry() then
            statehold(0);
        end;
        when receive(StartSignal) then
            transition(State2);
        end;
    end;
end;
end;

