couple CMOSImageSensorSystem
import architectureModels.ImageAcquisitionSystem as IAS;
import architectureModels.SignalProcessingSystem as SPS;
import architectureModels.PowerManagementSystem as PMS;
import architectureModels.DataTransmissionSystem as DTS;

part:
    IAS ImageAcquisitionInstance;
    SPS SignalProcessingInstance;
    PMS PowerManagementInstance;
    DTS DataTransmissionInstance;

connection:
